	@Test
	void acknowledgedObservationGenerationDoesNotBlockFreshWrites() throws Exception {
		RecordingSource backing = new RecordingSource();
		Statement captured = statement("captured-before-observation");
		Statement observed = statement("observation-after-transfer");
		Statement unrelated = statement("unrelated-after-acknowledgement");
		try (SailSourceBranch branch = branch(backing); SailSink original = branch.sink(IsolationLevels.NONE)) {
			original.approve(captured);
			original.flush();
			SailSource.FlushBatch batch = freeze(branch);
			try {
				original.observe(observed.getSubject(), observed.getPredicate(), observed.getObject(),
						observed.getContext());
				original.flush();
				batch.flush();
				batch.unFreezeAndDiscardFlushed();

				assertThrows(IllegalStateException.class, () -> original.approve(statement("sealed-alias")),
						"acknowledgement must keep the original sink alias sealed");
				try (SailSink fresh = branch.sink(IsolationLevels.NONE)) {
					fresh.approve(unrelated);
					assertDoesNotThrow(fresh::flush,
							"the acknowledged observation generation must not block an unrelated writer");
				}
				assertDoesNotThrow(branch::flush);
				assertTrue(backing.attempts.stream()
						.anyMatch(attempt -> attempt.contains("add:" + unrelated.getObject().stringValue())),
						"the unrelated statement must remain in the later published generation");
			} finally {
				batch.close();
			}
		}
	}

