	@Test
	void renewedSerializableAnchorAllowsUnrelatedParentWrite() throws Exception {
		assertRenewedSerializableAnchorPreservesReadBoundary(false);
	}

	private void assertRenewedSerializableAnchorPreservesReadBoundary(boolean competitorChangesObservedPattern)
			throws Exception {
		RecordingSource backing = new RecordingSource();
		Statement observed = statement("renewed-anchor-negative-read");
		Statement competitor = competitorChangesObservedPattern ? observed
				: statement("renewed-anchor-unrelated-write");
		try (SailSourceBranch root = branch(backing); SailSourceBranch child = branch(root)) {
			try (SailDataset dataset = child.dataset(IsolationLevels.SERIALIZABLE);
					CloseableIteration<? extends Statement> statements = dataset.getStatements(observed.getSubject(),
							observed.getPredicate(), observed.getObject(), observed.getContext())) {
				assertFalse(statements.hasNext(), "the serializable reader records the original negative observation");
			}

			write(child, "renewed-anchor-prefix-A");
			child.prepare();
			child.flush();

			SailSink capturedAlias = child.sink(IsolationLevels.NONE);
			SailSource.FlushBatch batch = null;
			try {
				capturedAlias.approve(statement("renewed-anchor-captured-B"));
				capturedAlias.flush();
				child.prepare();
				batch = freeze(child);
				batch.flush();
				batch.unFreezeAndDiscardFlushed();

				assertThrows(IllegalStateException.class,
						() -> capturedAlias.approve(statement("renewed-anchor-sealed-alias")),
						"acknowledgement keeps the captured generation's original alias sealed");
				try (SailSink writer = root.sink(IsolationLevels.NONE)) {
					writer.approve(competitor);
					writer.flush();
				}
				write(child, "renewed-anchor-later-C");
				if (competitorChangesObservedPattern) {
					assertThrows(SailConflictException.class, child::prepare,
							"carrier renewal preserves the original negative observation");
				} else {
					assertDoesNotThrow(child::prepare,
							"carrier renewal must not conflict with an unrelated parent statement");
					assertDoesNotThrow(child::flush);
					assertDoesNotThrow(root::flush);
				}
			} finally {
				if (batch != null) {
					batch.close();
				}
				capturedAlias.close();
			}
		}
	}

	@Test
	void serializableAnchorAcceptsFreshGenerationCreatedAfterAcknowledgement() throws Exception {
		assertSerializableAnchorAcceptsFreshGeneration(false);
	}

	@Test
	void serializableAnchorAcceptsFreshGenerationCreatedBeforeAcknowledgement() throws Exception {
		assertSerializableAnchorAcceptsFreshGeneration(true);
	}

	private void assertSerializableAnchorAcceptsFreshGeneration(boolean createLaterBeforeAcknowledgement)
			throws Exception {
		RecordingSource backing = new RecordingSource();
		Statement first = statement("serializable-anchor-first");
		Statement captured = statement("serializable-anchor-captured");
		Statement later = statement("serializable-anchor-later");
		try (SailSourceBranch root = branch(backing); SailSourceBranch child = branch(root)) {
			// Establish the persistent serializable backing carrier without recording a statement observation.
			try (SailDataset anchor = child.dataset(IsolationLevels.SERIALIZABLE)) {
			}

			write(child, first.getObject().stringValue());
			child.prepare();
			child.flush();

			SailSink capturedAlias = child.sink(IsolationLevels.NONE);
			SailSource.FlushBatch batch = null;
			try {
				capturedAlias.approve(captured);
				capturedAlias.flush();
				child.prepare();
				batch = freeze(child);
				if (createLaterBeforeAcknowledgement) {
					write(child, later.getObject().stringValue());
				}
				batch.flush();
				batch.unFreezeAndDiscardFlushed();

				assertThrows(IllegalStateException.class,
						() -> capturedAlias.approve(statement("sealed-serializable-alias")),
						"acknowledgement keeps aliases to the captured prefix sealed");
				if (!createLaterBeforeAcknowledgement) {
					write(child, later.getObject().stringValue());
				}
				assertDoesNotThrow(child::prepare,
						"the fresh serializable generation can be prepared after the captured prefix is acknowledged");
				assertDoesNotThrow(child::flush,
						"the fresh serializable generation can be flushed after the captured prefix is acknowledged");
				root.flush();

				List<String> additions = backing.attempts.stream()
						.flatMap(List::stream)
						.filter(attempt -> attempt.startsWith("add:"))
						.toList();
				assertEquals(3, additions.size(), "each generation must reach the backing source exactly once");
				assertEquals(Set.of("add:" + first.getObject().stringValue(),
						"add:" + captured.getObject().stringValue(), "add:" + later.getObject().stringValue()),
						new LinkedHashSet<>(additions), "the later generation remains exact across acknowledgement");
			} finally {
				if (batch != null) {
					batch.close();
				}
				capturedAlias.close();
			}
		}
	}

