	@Test
	void serializableAnchorRenewsWhenAcknowledgingEmptyChild() throws Exception {
		assertSerializableAnchorRenewsWithoutSecondPrepare(false);
	}

	private void assertSerializableAnchorRenewsWithoutSecondPrepare(boolean addSecondGeneration) throws Exception {
		RecordingSource backing = new RecordingSource();
		Statement first = statement("serializable-unprepared-first-A");
		Statement captured = statement("serializable-unprepared-captured-B");
		Statement later = statement("serializable-unprepared-later-C");
		try (SailSourceBranch root = branch(backing); SailSourceBranch child = branch(root)) {
			try (SailDataset anchor = child.dataset(IsolationLevels.SERIALIZABLE)) {
			}

			SailSink firstAlias = child.sink(IsolationLevels.NONE);
			SailSink capturedAlias = null;
			SailSource.FlushBatch batch = null;
			try {
				firstAlias.approve(first);
				firstAlias.flush();
				child.prepare();
				child.flush();

				if (addSecondGeneration) {
					capturedAlias = child.sink(IsolationLevels.NONE);
					capturedAlias.approve(captured);
					capturedAlias.flush();
				}
				batch = freeze(child);
				batch.flush();
				batch.unFreezeAndDiscardFlushed();

				assertThrows(IllegalStateException.class,
						() -> firstAlias.approve(statement("serializable-unprepared-sealed-A")),
						"acknowledgement keeps the prior prefix alias sealed");
				if (capturedAlias != null) {
					SailSink capturedAliasToAssert = capturedAlias;
					assertThrows(IllegalStateException.class,
							() -> capturedAliasToAssert.approve(statement("serializable-unprepared-sealed-B")),
							"acknowledgement keeps the unprepared captured alias sealed");
				}
				write(child, later.getObject().stringValue());
				assertDoesNotThrow(child::prepare,
						"the renewed serializable anchor prepares a generation after an unprepared ACK");
				assertDoesNotThrow(child::flush,
						"the renewed serializable anchor flushes a generation after an unprepared ACK");
				root.flush();

				List<String> additions = backing.attempts.stream()
						.flatMap(List::stream)
						.filter(attempt -> attempt.startsWith("add:"))
						.toList();
				Set<String> expected = addSecondGeneration
						? Set.of("add:" + first.getObject().stringValue(),
								"add:" + captured.getObject().stringValue(), "add:" + later.getObject().stringValue())
						: Set.of("add:" + first.getObject().stringValue(), "add:" + later.getObject().stringValue());
				assertEquals(expected.size(), additions.size(),
						"each surviving generation reaches backing exactly once");
				assertEquals(expected, new LinkedHashSet<>(additions), "the later generation remains exact after ACK");
			} finally {
				if (batch != null) {
					batch.close();
				}
				if (capturedAlias != null) {
					capturedAlias.close();
				}
				firstAlias.close();
			}
		}
	}

